     */
    static function cantidad($concepto)
    {
        $query = Doctrine_Query::create();
        $datos = $query->from('NomNivelestructural')->where("idconceptoestructural=?", $concepto)->count();
        return $datos;
    }

    /**
     * Función que se utiliza para devolver los datos pasando el start y el limit
     *
     * @param int   $limit    -límite de valores para realizar la consulta
     * @param int   $start    -comienzo para buscar los valores
     * @param mixed $concepto Concepto
     *
     * @return array
     */
    static function cargar($limit, $start, $concepto)
    {
        $query = Doctrine_Query::create();
        $datos = $query->select('n.*,c.*')
            ->from('NomNivelestructural n')
            ->where("n.idconceptoestructural=?", $concepto)->innerJoin('n.NomConceptonivel c')
            ->limit($limit)
            ->offset($start)
            ->execute()->toArray();

        $aux = array();
        $tmp = count($datos);
        for ($i = 0; $i < $tmp; $i++) {
            $temp ['id'] = $datos [$i] ['idnivelestructural'];
            $temp ['denominacion'] = $datos [$i] ['NomConceptonivel'] [0] ['denominacion'];
            $temp ['idconceptonivel'] = $datos [$i] ['NomConceptonivel'] [0] ['idconceptonivel'];
            $temp ['fechaini'] = $datos [$i] ['fechaini'];
            $temp ['fechafin'] = $datos [$i] ['fechafin'];
            $temp ['concepto'] = $datos [$i] ['concepto'];
            $temp ['raiz'] = $datos [$i] ['raiz'];
            $aux [] = $temp;
        }
        return $aux;
    }

