     * @param int $idconceptonivel       -id del concepto nivel
     * @param int $idnivelestructural    -id del nivel estructural
     *
     * @return array
     */
    static function comprobar($idconceptoestructural, $idconceptonivel, $idnivelestructural)
    {
        $query = Doctrine_Query::create();
        $cant = $query->from('NomNivelestructural')
            ->where(
                "idconceptoestructural=? and idconceptonivel=? and idnivelestructural <> ?",
                array($idconceptoestructural, $idconceptonivel, $idnivelestructural)
